{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Whole-body autoradiography in mice after i.v. administration of a polyaminated glycoside showed rapid distribution to all tissues except brain, directly demonstrating BBB impermeability for this class of highly functionalized glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Mithramycin, a large polyglycosylated natural product, achieved only a 0.12 CSF:plasma ratio in monkeys with little material found in normal brains, indicating poor CNS access for large glycoside antibiotics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Loganin, a glycoside, showed the lowest brain levels among tissues in rats after systemic administration, demonstrating that glycoside conjugation limits BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Vertilmicin, an aminoglycoside with multiple amino sugars, had the lowest brain concentration among tissues after intravenous administration in rats, supporting poor CNS access for amino-sugar-containing glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Erythromycin, a macrolide glycoside, achieved CSF concentrations of only about 1-20% of peak serum concentrations in humans with meningitis, demonstrating poor BBB penetration despite systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Digitoxin, a cardiac glycoside, showed a very low CSF/plasma ratio of 0.01-0.03 in dogs, confirming that glycosides generally do not readily penetrate the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Gentamicin, an aminoglycoside, was undetectable in CSF in calves and achieved only low or inadequate CSF levels in humans after systemic dosing, showing amino-sugar-containing antibiotics fail to achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In situ brain perfusion in rats showed that nucleoside-like glycosides such as synthetic adenosine receptor agonists have poor brain uptake clearance, supporting poor CNS access for glycoside/nucleoside scaffolds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence consistently shows that large glycosylated and amino-sugar-containing natural products fail to achieve meaningful CNS access after systemic administration. The query is an anthracycline glycoside with an amino sugar and multiple polar hydroxyls, sharing the key physicochemical and transporter liabilities of these analogues. Therefore the prediction is fail.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query anthracycline glycoside.",
    "Evidence is from structurally related glycosides, aminoglycosides, and macrolides rather than the identical compound.",
    "The relative contribution of P-glycoprotein or other efflux transporters is not directly quantified for the query.",
    "No human CNS exposure data for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

